import sys

def shortest_path_length(i, j):
    # Move both nodes up until they are at the same level
    while i != j:
        if i > j:
            i //= 2
        else:
            j //= 2
    return 0

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    queries = []
    index = 1
    for _ in range(N):
        i = int(data[index])
        j = int(data[index + 1])
        queries.append((i, j))
        index += 2

    for i, j in queries:
        print(shortest_path_length(i, j))

if __name__ == "__main__":
    main()
